            points += 2;
        }
        if (Integer.valueOf(0).equals(namesakeCount)) {
            points += 1;
        }
        if (householdMemberCount != null && householdMemberCount >= 3) {
            points += 2;
        }
        if (exceedsTenure(registrationDate)) {
            points += 3;
        }
        return points;
    }

